import os,json,subprocess,hashlib
from pathlib import Path
root=Path("/srv/projects/lowcost-europa")
unit=Path("/etc/systemd/system/lowcost-europa.service")
backup=Path("/usr/local/sbin/project-secrets-offsite-backup")
out={"project":{},"unit":{},"generic_backup":{},"active_processes":{},"source_checkout":{}}
for p in (root/"private/systemd-env/lowcost-europa.env",root/".venv/bin/gunicorn",root/"manage.py"):
 out["project"][p.relative_to(root).as_posix()]={"exists":p.exists(),"symlink":p.is_symlink()}
if unit.is_file():
 s=unit.read_text(errors="replace")
 out["unit"]={"safe_paths":[line for line in s.splitlines() if line.startswith(("WorkingDirectory=","ExecStart=","EnvironmentFile=","User="))],"unit_valid":subprocess.run(["systemd-analyze","verify",str(unit)],capture_output=True,timeout=12).returncode==0}
if backup.is_file():
 b=backup.read_bytes()
 out["generic_backup"]={"size":len(b),"sha256":hashlib.sha256(b).hexdigest(),"shebang":b.splitlines()[0].decode(errors="replace")[:70],"sh_syntax":subprocess.run(["sh","-n",str(backup)],capture_output=True,timeout=8).returncode==0,"old_paths":{s:b.count(s.encode()) for s in ("/etc/lowcost-europa","/var/lib/lowcost-europa","/var/backups/lowcost-europa","/root/project-secrets/lowcost-europa","/usr/local/sbin/project-secrets-offsite-backup")},"canonical_refs":b.count(b"/srv/projects/lowcost-europa")}
 refs=[]
 for f in Path("/etc/systemd/system").glob("*"):
  try:
   if f.is_file() and not f.is_symlink() and f.stat().st_size<60000 and str(backup) in f.read_text(errors="replace"):refs.append(f.name)
  except OSError:pass
 out["generic_backup"]["systemd_consumers"]=refs
for p in Path("/proc").iterdir():
 if not p.name.isdecimal():continue
 try:
  cmd=(p/"comm").read_text().strip()
  if cmd!="gunicorn":continue
  env=(p/"environ").read_bytes()
  out["active_processes"].setdefault("gunicorn",[]).append({"pid":int(p.name),"old_root_ref":b"/srv/lowcost-europa" in env,"new_root_ref":b"/srv/projects/lowcost-europa" in env})
 except OSError:pass
try:
 r=subprocess.run(["git","-C",str(root),"rev-parse","HEAD"],capture_output=True,text=True,timeout=8)
 out["source_checkout"]["head"]=r.stdout.strip() if r.returncode==0 else None
 s=subprocess.run(["git","-C",str(root),"status","--porcelain","--untracked-files=no"],capture_output=True,text=True,timeout=8)
 if s.returncode==0:out["source_checkout"]["modified_tracked_count"]=len(s.stdout.splitlines())
except Exception:pass
out["services"]={n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip() for n in ("lowcost-europa","nginx","pm2-root","pm2-iptvpn-bot","ssh")}
print(json.dumps(out,sort_keys=True))
